            send_num += 1;
            sys_move_cursor(1, print_location + 2);
            printf("[ECHO TASK] Echo no.%d packets ...\n", i);
            cur += recv_length[i];
        }
    }

    sys_shmpage_dt((void*)vars);

    return 0;
